import React, { useState, useEffect } from "react";
import { checkout } from "../api/api";
import { useNavigate } from "react-router-dom";
import { jwtDecode } from "jwt-decode";
import "./Checkout.css";

export default function Checkout() {
  const [total, setTotal] = useState(null);
  const [user, setUser] = useState({ name: "", email: "" });
  const [billingTime, setBillingTime] = useState("");
  const [loading, setLoading] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const navigate = useNavigate();

  useEffect(() => {
    // Decode token to extract user info
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        setUser({
          name: decoded.name || "Unknown User",
          email: decoded.email || "No email found",
        });
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }

    // Set current billing time
    const now = new Date();
    const formattedTime = now.toLocaleString("en-IN", {
      dateStyle: "full",
      timeStyle: "short",
    });
    setBillingTime(formattedTime);
  }, []);

  const handleCheckout = async () => {
    setLoading(true);
    try {
      const res = await checkout();
      setTotal(res.data.total);
    } catch {
      alert("Checkout failed");
    } finally {
      setLoading(false);
    }
  };

  const handleConfirm = () => {
    setConfirming(true);
    setTimeout(() => {
      alert("Payment successful!");
      navigate("/");
    }, 800);
  };

  return (
    <div className="checkout-page">
      <div className="checkout-container">
        <div className="checkout-header">
          <h1 className="checkout-title">Checkout</h1>
          <p className="checkout-subtitle">Complete Your Purchase</p>
        </div>

        <div className="checkout-content">
          {/* Billing Information */}
          <div className="checkout-section">
            <h2 className="section-title">Billing Information</h2>
            <div className="info-card">
              <div className="info-row">
                <span className="info-label">Customer Name</span>
                <span className="info-value">{user.name}</span>
              </div>
              <div className="info-divider"></div>
              <div className="info-row">
                <span className="info-label">Email Address</span>
                <span className="info-value">{user.email}</span>
              </div>
              <div className="info-divider"></div>
              <div className="info-row">
                <span className="info-label">Billing Date & Time</span>
                <span className="info-value">{billingTime}</span>
              </div>
            </div>
          </div>

          {/* Order Summary */}
          <div className="checkout-section">
            <h2 className="section-title">Order Summary</h2>
            
            {!total ? (
              <div className="summary-card">
                <p className="summary-message">
                  Click below to generate your final bill and review the total amount
                </p>
                <button 
                  className={`generate-bill-btn ${loading ? 'loading' : ''}`}
                  onClick={handleCheckout}
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <span className="btn-spinner"></span>
                      Generating...
                    </>
                  ) : (
                    'Generate Final Bill'
                  )}
                </button>
              </div>
            ) : (
              <div className="summary-card total-card">
                <div className="total-section">
                  <span className="total-label">Total Payable</span>
                  <span className="total-amount">₹{total.toLocaleString()}</span>
                </div>
                <div className="payment-info">
                  <p className="payment-note">
                    <svg className="info-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <circle cx="12" cy="12" r="10"/>
                      <line x1="12" y1="16" x2="12" y2="12"/>
                      <line x1="12" y1="8" x2="12.01" y2="8"/>
                    </svg>
                    Secure payment processing
                  </p>
                </div>
                <button 
                  className={`confirm-payment-btn ${confirming ? 'confirming' : ''}`}
                  onClick={handleConfirm}
                  disabled={confirming}
                >
                  {confirming ? (
                    <>
                      <span className="btn-spinner"></span>
                      Processing...
                    </>
                  ) : (
                    'Confirm Payment'
                  )}
                </button>
                <button 
                  className="back-to-cart-btn"
                  onClick={() => navigate("/cart")}
                  disabled={confirming}
                >
                  Back to Cart
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
